        qo_output.mode = QO_WAIT;
        qo_output.good = 0U;
        qo_output.usable = 0U;
        return;
    }

    /* 配置校验：malformed → FAULT */
    if ((!isfinite(qo_config.minimum_weight)) || (qo_config.minimum_weight <= 0.0) ||
        (!isfinite(qo_config.minimum_separation_sine)) ||
        (qo_config.minimum_separation_sine <= 0.0) ||
        (qo_config.minimum_separation_sine > 1.0) ||
        (qo_config.required_good < 1U) || (qo_config.required_good > 10U) ||
        (qo_config.max_consecutive_bad > 10U)) {
        qo_state.mode = QO_FAULT;
        qo_output.mode = QO_FAULT;
        return;
    }

    /* 输入结构校验：NULL / count 不合法 → FAULT */
    if ((qo_input.body == NULL) || (qo_input.reference == NULL) || (qo_input.weights == NULL) ||
        (qo_input.count < 2U) || (qo_input.count > 3U)) {
        qo_state.mode = QO_FAULT;
        qo_output.mode = QO_FAULT;
        return;
    }

    /* 逐项校验 */
    for (i = 0U; i < qo_input.count; i++) {
        if ((!isfinite(qo_input.weights[i])) || (qo_input.weights[i] <= 0.0)) {
            malformed = 1;
            break;
        }
        if ((!adcs_is_finite_vec3(&qo_input.body[i])) ||
            (!adcs_is_finite_vec3(&qo_input.reference[i]))) {
            malformed = 1;
            break;
        }
        if (adcs_vec3_normalize(&qo_input.body[i], ADCS_EPS_NORM, &b_unit[i]) != ADCS_OK) {
            malformed = 1;
            break;
        }
        if (adcs_vec3_normalize(&qo_input.reference[i], ADCS_EPS_NORM, &r_unit[i]) != ADCS_OK) {
            malformed = 1;
            break;
        }
    }

    if (malformed) {
        qo_state.mode = QO_FAULT;
        qo_output.mode = QO_FAULT;
        return;
    }

    /* 累加 weighted_body、total_weight、weighted alignment */
    qo_output.weighted_body = zero3;
    for (i = 0U; i < qo_input.count; i++) {
        adcs_vec3_t term;
        double w = qo_input.weights[i];
        double d = adcs_vec3_dot(&b_unit[i], &r_unit[i]);
        term = adcs_vec3_scale(&b_unit[i], w);
        qo_output.weighted_body = adcs_vec3_add(&qo_output.weighted_body, &term);
        qo_output.total_weight += w;
        alignment_sum += w * d;
    }

    qo_output.usable = (uint32_t)qo_input.count;

    if (qo_output.total_weight > 0.0) {
        qo_output.mean_alignment = alignment_sum / qo_output.total_weight;
    } else {
        qo_output.mean_alignment = 0.0;
    }

    /* 计算两个 separation sine（用前两个观测的单位向量叉乘范数） */
    {
        adcs_vec3_t c1 = adcs_vec3_cross(&b_unit[0], &b_unit[1]);
        adcs_vec3_t c2 = adcs_vec3_cross(&r_unit[0], &r_unit[1]);
        qo_output.body_separation_sine = adcs_vec3_norm(&c1);
        qo_output.reference_separation_sine = adcs_vec3_norm(&c2);
    }

    /* usable 判定 */
    if ((qo_output.total_weight >= qo_config.minimum_weight) &&
        (qo_output.body_separation_sine >= qo_config.minimum_separation_sine) &&
        (qo_output.reference_separation_sine >= qo_config.minimum_separation_sine)) {
        usable_flag = 1;
    } else {
        usable_flag = 0;
    }

    if (usable_flag) {
        qo_state.good += 1U;
        qo_state.bad_streak = 0U;
        if (qo_state.good >= qo_config.required_good) {
            qo_state.mode = QO_SOLVE;
        } else {
            qo_state.mode = QO_WAIT;
        }
    } else {
        qo_state.bad_streak += 1U;
        if (qo_state.bad_streak > qo_config.max_consecutive_bad) {
            qo_state.mode = QO_WAIT;
            qo_state.good = 0U;
            qo_state.bad_streak = 0U;
        } else {
            qo_state.mode = QO_HOLD;
        }
    }

    qo_output.mode = qo_state.mode;
    qo_output.good = qo_state.good;
}
